import{_ as a,o as n,a as p,b as l}from"./app.C41L12d5.js";const c="/ascendc.github.io/assets/Fixpipe_NZ2ND.CVo7uAwP.png",N=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"矩阵计算（ISASI）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI"},{"text":"矩阵搬出关键特性说明","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_key_features/cube_store_key_features"},{"text":"NZ2ND","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_key_features/NZ2ND"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_key_features/NZ2ND.md","filePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_key_features/NZ2ND.md","outlineHeaders":[{"level":2,"title":"特性说明","slug":"特性说明","link":"#特性说明"},{"level":2,"title":"特性约束","slug":"特性约束","link":"#特性约束"},{"level":2,"title":"使用示例","slug":"使用示例","link":"#使用示例"}],"lastUpdated":1785832713000}'),e={name:"api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_key_features/NZ2ND.md"};function i(t,s,_,d,r,o){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>NZ2ND<span id="ZH-CN_TOPIC_0000002568950981"></span></h1><h2 id="特性说明">特性说明<a class="header-anchor" href="#特性说明">​</a></h2><p>矩阵搬出时，NZ2ND功能即为实现NZ格式到ND格式的矩阵转换。</p><p>NZ2ND转化过程可以参考以下伪代码：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">ndNum</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="o">++</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="c1">// fractal_size = 16 * sizeof(L0C_element)</span>
<span class="w">    </span><span class="n">src_temp_nd_addr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">src</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">srcNdStride</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">fractal_size</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">i</span><span class="p">;</span>
<span class="w">    </span><span class="n">dst_temp_nd_addr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">dst</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">dstNdStride</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">dst_element</span><span class="p">)</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">i</span><span class="p">;</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="n">j</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">j</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">mSize</span><span class="p">;</span><span class="w"> </span><span class="n">j</span><span class="o">++</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">src_temp_n_addr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">src_temp_nd_addr</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">j</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">16</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">L0C_element</span><span class="p">);</span>
<span class="w">        </span><span class="n">dst_temp_n_addr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">dst_temp_nd_addr</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">j</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">dstStride</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">dst_element</span><span class="p">);</span>
<span class="w">        </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="n">k</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">k</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">ceil</span><span class="p">(</span><span class="n">nSize</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="mi">16</span><span class="p">);</span><span class="w"> </span><span class="n">k</span><span class="o">++</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">            </span><span class="n">src_block_addr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">src_temp_n_addr</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">k</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">srcStride</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">16</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">L0C_element</span><span class="p">);</span>
<span class="w">            </span><span class="n">dst_block_addr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">dst_temp_n_addr</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">k</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">16</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">dst_element</span><span class="p">);</span>
<span class="w">        </span><span class="p">}</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div><p>伪代码使用的参数具体说明如下：</p><ul><li>src表示源操作数搬运的起始地址。</li><li>dst表示目的操作数搬运的起始地址。</li><li>源操作数每个NZ矩阵的起始地址为src_temp_nd_addr。</li><li>目的操作数每个ND矩阵的起始地址为dst_temp_nd_addr。</li><li>源操作数中每个NZ矩阵中每一行的起始地址为src_temp_n_addr。</li><li>目的操作数每个ND矩阵中每一行的起始地址为dst_temp_n_addr。</li><li>在每一行中，以16个数据为一个数据块，源操作数每块数据块的起始地址为src_block_addr，目的操作数中每一块数据块的起始地址为dst_block_addr。</li></ul><p>以下参数为NZ2ND用户可配置参数，含义及取值范围参见<a href="../cube_compute_store/Fixpipe_L0CToGM.html">Fixpipe搬运参数</a>与<a href="../cube_compute_store/Fixpipe_L0CToGM.html">参数说明</a>：</p><ul><li>mSize与nSize分别表示矩阵m方向和n方向上的维度。</li><li>srcStride表示NZ矩阵中不同Z分形列的间隔，单位为C0_Size。</li><li>dstStride表示目标ND矩阵中不同行的间隔，单位为元素。</li><li>ndNum表示需要做NZ2ND转化的矩阵个数。</li><li>srcNdStride表示不同NZ矩阵之间的间隔，单位为16*C0_Size（C0_Size=16*sizeof(T)，T为操作数的数据类型）字节。</li><li>dstNdStride表示不同目标ND矩阵之间的间隔，单位为元素。</li></ul><h2 id="特性约束">特性约束<a class="header-anchor" href="#特性约束">​</a></h2><ul><li>当开启Channel Split/Channel Merge功能（NZ2NZ）时，此功能不可用。</li><li>目标操作数地址之间不能重叠。</li></ul><h2 id="使用示例">使用示例<a class="header-anchor" href="#使用示例">​</a></h2><p>如下图所示，在L0C Buffer中有两个NZ格式的矩阵，每个矩阵N方向上维度为32，M方向上维度为48，经过NZ2ND转换，将数据格式变为右部分所示排布。</p><p><strong>图1</strong> NZ2ND示意图<span id="zh-cn_topic_0000002547300777_fig862819576334"></span></p><p><img src="`+c+'" alt></p><p>对于该场景，可以通过配置intriParams结构体参数实现上图的效果：</p><ul><li>ndNum = 2，表示需要做NZ2ND转化的矩阵个数为2。</li><li>nSize = 32，表示源NZ矩阵在N方向上的大小为32个元素。</li><li>mSize = 48，表示源NZ矩阵在M方向上的大小为48个元素。</li><li>srcStride = 64，表示源NZ矩阵中相邻Z排布的起始地址之间的间隔为64 * C0_Size(C0_Size = 16*sizeof(T)，T为操作数的数据类型)字节。</li><li>dstStride = 64，表示目的ND矩阵每一行中的元素个数为64。</li><li>srcNdStride = 256，表示不同NZ矩阵起始地址之间的间隔为256 * C0_Size字节。</li><li>dstNdStride = 4096，表示目的相邻ND矩阵起始地址之间的偏移为4096个元素。</li></ul></article></div>',1)])])}const m=a(e,[["render",i]]);export{N as __pageData,m as default};
